// Rendering adapted from the original Miro extension's dashboard.js. Instead of the hard-coded
// mock object, the data comes from data.js, generated by pipeline/build-dashboard.mjs.
const DATA = window.MIRO_DASHBOARD_DATA;
// The overview shows one source variant at a time (see sources.js); all sources by default.
let D = DATA;
const REPO_URL = 'https://github.com/Isabelslorer/cognition-trends';

window.addEventListener('miro:route',(event)=>{if(event.detail==='areas')fitBubbles();});
window.addEventListener('resize',()=>fitBubbles());

document.addEventListener('DOMContentLoaded',()=>{
  if(!D){
    renderEmptyState();
    return;
  }
  renderMeta();
  renderBubbles();
  renderSliders();
  renderProfile();
  if(D.meta.demo) renderDemoNote();
});

window.addEventListener('miro:source',(event)=>{
  if(!DATA) return;
  D=DATA.variants?.[event.detail.source]||DATA;
  closeBubble();
  renderMeta();
  renderBubbles();
  renderSliders();
  renderProfile();
});

function renderEmptyState(){
  const status=document.getElementById('coverStatus');
  status.textContent='No data yet. Run the pipeline (see README.md) to generate data.js next to this page.';
  status.hidden=false;
  document.getElementById('coverStart').remove();
  document.querySelector('.tb-nav').remove();
}

function renderMeta(){
  const chats=`${D.meta.chatCount} chat${D.meta.chatCount===1?'':'s'}`;
  const whose=D.meta.demo?`${D.meta.demo} · `:'';
  document.querySelectorAll('.page-foot-meta').forEach(el=>{el.textContent=`${whose}Based on ${chats}`;});
}

// The made-up example (demo-data.js): say so on the cover and point to running it on your own chats.
function renderDemoNote(){
  const status=document.getElementById('coverStatus');
  status.innerHTML=`Showing an example: ${esc(D.meta.demo.toLowerCase())}. <a href="${REPO_URL}#try-it-with-your-own-chats" target="_blank" rel="noopener">Try it with your own chats</a>`;
  status.hidden=false;
}

function renderBubbles(){
  const stage=document.getElementById('bubbleStage');
  stage.innerHTML = '';
  D.areas.forEach((a)=>{
    const el=document.createElement('button');
    el.type='button';
    el.className=`bubble ${a.size}`;
    el.style.left=`${a.x}%`;
    el.style.top=`${a.y}%`;
    el.setAttribute('aria-pressed','false');
    el.innerHTML=`<span class="bubble-label">${esc(a.label)}</span><span class="bubble-pct">${a.pct}%</span>`;
    el.addEventListener('click',()=>openBubble(a,el));
    stage.appendChild(el);
  });
}

// Bubble sizes are set for an 820×560 stage. A narrower stage gets a matching shorter height; a stage that is
// shorter (CSS shrinks it on short windows) or narrower shrinks the bubbles with it.
function fitBubbles(){
  const stage=document.getElementById('bubbleStage');
  if(!stage||!stage.clientWidth) return;
  const widthScale=Math.min(1,stage.clientWidth/820);
  stage.style.height='';
  const height=Math.round(560*Math.max(widthScale,0.6));
  if(height<stage.clientHeight) stage.style.height=`${height}px`;
  const scale=Math.min(widthScale,stage.clientHeight/560);
  stage.style.setProperty('--bubble-scale',scale.toFixed(3));
}

function openBubble(area,el){
  const all=document.querySelectorAll('.bubble');
  if(el.classList.contains('active')){
    closeBubble();
    return;
  }
  all.forEach(b=>{b.classList.toggle('active',b===el);b.setAttribute('aria-pressed',String(b===el));});

  document.getElementById('bpPlaceholder').style.display='none';
  const c=document.getElementById('bpContent');
  c.className='bp-content open';
  c.innerHTML=`
    <div class="bp-top">
      <div>
        <div class="bp-title">${esc(area.label)}</div>
        <div class="bp-pct">${area.pct}% of your AI activity · ${area.sessions} chat${area.sessions===1?'':'s'}</div>
      </div>
      <button class="bp-close" type="button" aria-label="Close area detail">×</button>
    </div>
    <div class="bp-section">
      <div class="label">What it usually involves</div>
      <div class="bp-text">${esc(area.includes)}</div>
    </div>
    <div class="bp-section">
      <div class="label">The pattern</div>
      <div class="bp-text">${esc(area.patterns)}</div>
    </div>
    <div class="bp-section bp-try">
      <div class="label">Try this next time</div>
      <div class="bp-text">${esc(area.try)}</div>
    </div>
  `;
  c.querySelector('.bp-close')?.addEventListener('click', closeBubble);
}

function closeBubble(){
  document.querySelectorAll('.bubble').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-pressed','false');});
  document.getElementById('bpPlaceholder').style.display='flex';
  document.getElementById('bpContent').className='bp-content';
  document.getElementById('bpContent').innerHTML='';
}

function renderSliders(){
  const table=document.getElementById('slidersCard');
  table.innerHTML=D.aspects.map(a=>`
    <button class="split-row" type="button" aria-expanded="false">
      <span class="split-label">${esc(a.label)}</span>
      <span class="split-end ai" aria-hidden="true">AI</span>
      <span class="split-track" aria-hidden="true">
        <span class="split-base"></span>
        <span class="split-band" style="left:${a.lo}%;width:${a.hi-a.lo}%;--mid:${bandMid(a)}%"></span>
        <span class="split-dot" style="left:${a.position}%"></span>
      </span>
      <span class="split-end you" aria-hidden="true">You</span>
      <span class="split-verdict ${esc(a.tone)}">${esc(a.verdict)}<span class="split-toggle" aria-hidden="true">+</span></span>
      <span class="split-detail">
        ${a.question?`<span class="split-question">${esc(a.question)}</span>`:''}
        <span class="split-line">${esc(a.trendLine)} ${esc(a.detail)}</span>
        ${a.footnote||a.basis?`<span class="split-line basis">${esc(a.footnote||a.basis)}</span>`:''}
      </span>
    </button>`).join('');
  table.querySelectorAll('.split-row').forEach(row=>{
    row.addEventListener('click',()=>{
      const was=row.classList.contains('open');
      table.querySelectorAll('.split-row').forEach(r=>{
        r.classList.remove('open');
        r.setAttribute('aria-expanded','false');
        r.querySelector('.split-toggle').textContent='+';
      });
      if(!was){
        row.classList.add('open');
        row.setAttribute('aria-expanded','true');
        row.querySelector('.split-toggle').textContent='−';
      }
    });
  });
}

// Where the band crosses the middle of the bar, as a share of the band's own width: blue before, sand after.
function bandMid(a){
  if(a.hi<=a.lo) return a.lo<50?100:0;
  return Math.max(0,Math.min(100,(50-a.lo)/(a.hi-a.lo)*100)).toFixed(1);
}

function renderProfile(){
  const g=document.getElementById('profileGrid');
  const p=D.profile;
  const card=(cls,label,c)=>`
      <div class="profile-card ${cls}">
        <div class="label">${label}</div>
        <div class="pc-title">${esc(c.title)}</div>
        <div class="pc-body">${rich(c.body)}</div>
      </div>`;
  g.innerHTML=`
    <div class="profile-lead">
      <div class="profile-lead-title">${esc(p.heroTitle)}</div>
      <div class="profile-lead-body">${rich(p.summary)}</div>
    </div>
    <div class="profile-cards">
      ${card('you','You tend to be',p.you)}
      ${card('ai','AI tends to become',p.ai)}
      ${card('together','Together, the pattern is',p.together)}
    </div>
    <div class="profile-tips">
      <div class="profile-tip"><div class="label">What's working</div><p>${esc(p.helps)}</p></div>
      <div class="profile-tip prompt"><div class="label">Prompt better</div><p>${esc(p.risk)}</p></div>
      <div class="profile-tip"><div class="label">Watch for</div><p>${esc(p.next)}</p></div>
    </div>
  `;
}

function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}

// Generated copy may bold a phrase with **...**; everything else is escaped.
function rich(v){return esc(v).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>');}
